fn apply(op: i32, a: i32, b: i32) -> i32 {
    match op {
        1 => a + b,
        2 => a - b,
        3 => a * b,
        4 => if b == 0 { 0 } else { a / b },
        _ => b,
    }
}

fn key_digit(idx: i32) -> i32 {
    match idx {
        0 => 7,
        1 => 8,
        2 => 9,
        4 => 4,
        5 => 5,
        6 => 6,
        8 => 1,
        9 => 2,
        10 => 3,
        13 => 0,
        _ => -1,
    }
}

fn key_char(idx: i32) -> i32 {
    match idx {
        3 => 43,
        7 => 45,
        11 => 42,
        12 => 67,
        14 => 61,
        15 => 47,
        _ => 32,
    }
}

fn op_of(idx: i32) -> i32 {
    match idx {
        3 => 1,
        7 => 2,
        11 => 3,
        15 => 4,
        _ => 0,
    }
}

fn frame(t: i32) {
    host::display::clear(0x0d0d10);
    host::display::fill_rect(16, 24, 480, 70, 0x1a1e26);
    host::display::draw_number(36, 44, host::display::state_get(1), 0xffffff, 4);
    let pending: i32 = host::display::state_get(3);
    if pending != 0 {
        host::display::draw_char(460, 44, key_char(match pending {
            1 => 3,
            2 => 7,
            3 => 11,
            _ => 15,
        }), 0xffcc33, 3);
    }

    let mut idx: i32 = 0;
    while idx < 16 {
        let x: i32 = 16 + (idx % 4) * 124;
        let y: i32 = 120 + (idx / 4) * 92;
        host::display::fill_rect(x, y, 116, 84, 0x232833);
        let d: i32 = key_digit(idx);
        if d >= 0 {
            host::display::draw_number(x + 48, y + 30, d, 0xffffff, 3);
        } else {
            host::display::draw_char(x + 48, y + 30, key_char(idx), 0xffcc33, 3);
        }
        idx = idx + 1;
    }

    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);
    if down == 1 && prev == 0 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        if px >= 16 && py >= 120 {
            let c: i32 = (px - 16) / 124;
            let r: i32 = (py - 120) / 92;
            if c < 4 && r < 4 {
                let k: i32 = r * 4 + c;
                let d2: i32 = key_digit(k);
                let entry: i32 = host::display::state_get(1);
                if d2 >= 0 {
                    let mut e: i32 = entry;
                    if host::display::state_get(4) == 1 {
                        e = 0;
                        host::display::state_set(4, 0);
                    }
                    if e < 1000000 {
                        host::display::state_set(1, e * 10 + d2);
                    }
                } else if k == 12 {
                    host::display::state_set(1, 0);
                    host::display::state_set(2, 0);
                    host::display::state_set(3, 0);
                    host::display::state_set(4, 0);
                } else if k == 14 {
                    if host::display::state_get(3) != 0 {
                        let res: i32 = apply(host::display::state_get(3), host::display::state_get(2), entry);
                        host::display::state_set(2, res);
                        host::display::state_set(1, res);
                        host::display::state_set(3, 0);
                        host::display::state_set(4, 1);
                    }
                } else {
                    if host::display::state_get(3) != 0 && host::display::state_get(4) == 0 {
                        let res2: i32 = apply(host::display::state_get(3), host::display::state_get(2), entry);
                        host::display::state_set(2, res2);
                        host::display::state_set(1, res2);
                    } else {
                        host::display::state_set(2, entry);
                    }
                    host::display::state_set(3, op_of(k));
                    host::display::state_set(4, 1);
                }
            }
        }
    }
    host::display::present();
}
